Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_prepend_resize_failure(void) {
    // Setup: create a buffer with content "world"
    buffer_t *buf = helper_create_buffer_with_content("world");
    TEST_ASSERT_NOT_NULL(buf);

    // The buffer's allocated size is just enough for "world" (5 chars + null)
    // Prepending "hello" (5 chars) will require resizing: needed = 5 + 5 = 10
    // Force buffer_resize to fail by failing the next allocation (realloc in buffer_resize)
    // helper_create_buffer_with_content does 2 allocations (struct + data)
    malloc_fail_after(2); // Fail the 3rd allocation (realloc in buffer_resize)

    int ret = buffer_prepend(buf, "hello");
    TEST_ASSERT_EQUAL_INT(-1, ret);

    // Buffer should still be valid, original content unchanged
    helper_assert_buffer_equals(buf, "world");
    helper_assert_buffer_length(buf, 5);

    // Cleanup
    helper_free_buffer(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_resize_failure);
    return UNITY_END();
}

